import React, { useState, useEffect } from 'react';
import './App.css'; // Optional: add your own styling here
import NotificationHandler from './NotificationHandler';
import Navbar from './Navbar'; 
import Auth from './Auth';

const { login, fetchSecureData, logout } = Auth;


export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  
  // Dashboard states
  const [sightingId, setSightingId] = useState('');
  const [newAdmin, setNewAdmin] = useState({ username: '', password: '' });

  const BASE_URL = 'http://localhost:8080/api/admin';

  const [mapTrigger, setMapTrigger] = useState(0);

  // The callback function
  const handleNewAlert = () => setMapTrigger(prev => prev + 1);

  // 🔐 Login Flow
  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${BASE_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password })
      });
      if (res.ok) {
        setIsLoggedIn(true);
      } else {
        alert('❌ Invalid credentials');
      }
    } catch (err) {
      console.error(err);
    }
  };

  // 👑 Create Admin
  const handleCreateAdmin = async () => {
    try {
      const res = await fetch(`${BASE_URL}/newadmin`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newAdmin)
      });
      const data = await res.json();
      alert(data.message || 'Admin action completed');
    } catch (err) {
      console.error(err);
    }
  };

  // ✅ Verify Sighting
  const handleVerify = async () => {
    try {
      const res = await fetch(`${BASE_URL}/sightings/${sightingId}/verify`,
         { method: 'PUT', 
          headers: { 
            'Content-Type': 'application/json'
          ,'Authorization': `Bearer ${localStorage.getItem('authToken')}`
           }
         });
      const text = await res.text();
      alert(text);
    } catch (err) {
      console.error(err);
    }
  };


  //🖥️ UI Render
  if (!isLoggedIn) {
    return (
      <div style={{ padding: '2rem' }}>
        <h2>Admin Login 🔐</h2>
        <form onSubmit={handleLogin}>
          <input placeholder="Username" onChange={(e) => setUsername(e.target.value)} required />
          <input type="password" placeholder="Password" onChange={(e) => setPassword(e.target.value)} required />
          <button type="submit" onClick={() => login(username, password)}>Login</button>
        </form>
      </div>
    );
  }

  return (
    <div style={{ padding: '2rem' }}>

      <h1>Dashboard 🎛️</h1>
      <NotificationHandler onNewAlert={handleNewAlert} />

      <hr />
        <Navbar BASE_URL={BASE_URL} mapTrigger={mapTrigger} />
    
      <hr/>

      <button onClick={() => { setIsLoggedIn(false); logout(); }}>Logout</button>

      <hr />
    </div>
  );
}
